"""
Copied from pytest
"""

from _pytest.assertion import truncate
from _pytest.assertion import util


def activate_assert_rewrite(item):
    def callbinrepr(op, left, right):
        hook_result = item.ihook.pytest_assertrepr_compare(
            config=item.config, op=op, left=left, right=right
        )
        for new_expl in hook_result:
            if new_expl:
                new_expl = truncate.truncate_if_required(new_expl, item)
                new_expl = [line.replace("\n", "\\n") for line in new_expl]
                res = "\n~".join(new_expl)
                if item.config.getvalue("assertmode") == "rewrite":
                    res = res.replace("%", "%%")
                return res
        return None

    util._reprcompare = callbinrepr

import asyncio
import inspect
import types
from typing import List
from typing import Union

from _pytest.fixtures import FixtureDef
from _pytest.fixtures import FixtureRequest
from _pytest.fixtures import FuncFixtureInfo
from _pytest.fixtures import resolve_fixture_function
from _pytest.nodes import Item


class Ignore(Exception):
    pass


def function_args(func):
    return func.__code__.co_varnames[: func.__code__.co_argcount]


def _get_fixture(item, arg_name, fixture=None):
    """
    Sometimes fixture names clash with plugin fixtures.
    We prioritise fixtures that are defined inside the user's module
    """
    if arg_name == "request":
        # Support parameterized fixture
        if fixture:
            try:
                item._request.param = item._pyfuncitem.callspec.params[fixture.argname]
            except (AttributeError, KeyError):
                pass

        return item._request

    if arg_name == "self":
        raise Ignore

    _fixtureinfo = item._fixtureinfo
    fixtures = sorted(
        _fixtureinfo.name2fixturedefs[arg_name], key=lambda x: x.has_location
    )

    return fixtures[-1]


async def fill_fixtures(item: Item):
    fixture_values = []
    teardowns = []

    # Important to maintain order of fixtures specified by function
    fixture_names: List[str] = list(function_args(item.function))

    # Add fixtures not specified in function arguments (eg. autouse)
    for fixture_name in item._fixtureinfo.initialnames:
        if fixture_name not in fixture_names:
            fixture_names.append(fixture_name)

    fixtures = []
    are_autouse = []
    for fixture_name in fixture_names:
        try:
            fixture = _get_fixture(item, fixture_name)
        except Ignore:
            continue

        is_autouse = fixture_name not in function_args(item.function)

        if fixture.scope not in ["function", "module", "session"]:
            raise Exception(f"{fixture.scope} scope not supported")

        fixtures.append(fixture)
        are_autouse.append(is_autouse)

    # Fill fixtures concurrently
    fill_results = await asyncio.gather(
        *(
            fill_fixture_fixtures(item._fixtureinfo, fixture, item)
            for fixture in fixtures
        )
    )

    for (value, extra_teardowns), is_autouse in zip(fill_results, are_autouse):
        teardowns.extend(extra_teardowns)

        if not is_autouse:
            fixture_values.append(value)

    # Slight hack to stop the regular fixture logic from running
    item.fixturenames = []

    return fixture_values, teardowns


async def _fill_fixture_fixtures(
    _fixtureinfo: FuncFixtureInfo, fixture: FixtureDef, item: Item
):
    values = []
    all_teardowns = []
    for arg_name in function_args(fixture.func):
        try:
            dep_fixture = _get_fixture(item, arg_name, fixture)
        except Ignore:
            continue

        value, teardowns = await fill_fixture_fixtures(_fixtureinfo, dep_fixture, item)
        values.append(value)
        all_teardowns.extend(teardowns)
    return values, all_teardowns


class CachedFunctionBase(object):
    def __init__(self, wrapped_func):
        self.lock = asyncio.Lock()
        self.wrapped_func = wrapped_func

        # Trying to fool pytest's use of inspect.isgeneratorfunction
        self.__defaults__ = getattr(wrapped_func, "__defaults__", None)
        self.__kwdefaults__ = getattr(wrapped_func, "__kwdefaults__", None)
        self.__annotations__ = getattr(wrapped_func, "__annotations__", {})

    @property
    def __code__(self):
        return self.wrapped_func.__code__

    @property
    def __name__(self):
        return self.wrapped_func.__name__


class CachedFunction(CachedFunctionBase):
    async def __call__(self, *args, **kwargs):
        async with self.lock:
            if hasattr(self, "value"):
                return self.value
            if hasattr(self, "exception"):
                raise self.exception
            try:
                if inspect.iscoroutinefunction(self.wrapped_func):
                    self.value = await self.wrapped_func(*args, **kwargs)
                else:
                    self.value = self.wrapped_func(*args, **kwargs)
            except Exception as e:
                self.exception = e
                raise
            return self.value


class GenCounter:
    def __init__(self, parent):
        self.num_calls = 0
        self.parent = parent

    def __iter__(self):
        return self

    def __next__(self):
        self.num_calls += 1
        if self.num_calls == 2:
            self.parent.completed(self)
        return self.parent.__next__()


class CachedGen(CachedFunctionBase):
    """Save the result of the 1st yield.
    Yield 2nd yield when all callers have yielded."""

    def __init__(self, wrapped_func):
        super().__init__(wrapped_func)
        self.instances = set()

    def completed(self, instance):
        self.instances.remove(instance)

    def __call__(self, *args, **kwargs):
        self.args = args
        self.kwargs = kwargs
        instance = GenCounter(self)
        self.instances.add(instance)
        return instance

    def __next__(self):
        if len(self.instances) == 0:
            return self.gen.__next__()
        if hasattr(self, "value"):
            return self.value
        if hasattr(self, "exception"):
            raise self.exception
        else:
            try:
                gen = self.wrapped_func(*self.args, **self.kwargs)
                self.gen = gen
                self.value = gen.__next__()
            except Exception as e:
                self.exception = e
                raise
            return self.value


class AsyncGenCounter:
    def __init__(self, parent):
        self.num_calls = 0
        self.parent = parent

    def __aiter__(self):
        return self

    async def __anext__(self):
        self.num_calls += 1
        if self.num_calls == 2:
            self.parent.completed(self)
        return await self.parent.__anext__()


class CachedAsyncGen(CachedFunctionBase):
    """Save the result of the 1st yield.
    Yield 2nd yield when all callers have yielded."""

    def __init__(self, wrapped_func):
        super().__init__(wrapped_func)
        self.instances = set()

    def completed(self, instance):
        self.instances.remove(instance)

    def __call__(self, *args, **kwargs):
        self.args = args
        self.kwargs = kwargs
        instance = AsyncGenCounter(self)
        self.instances.add(instance)
        return instance

    async def __anext__(self):
        if len(self.instances) == 0:
            return await self.gen.__anext__()
        async with self.lock:
            if hasattr(self, "value"):
                return self.value
            if hasattr(self, "exception"):
                raise self.exception
            else:
                try:
                    gen = self.wrapped_func(*self.args, **self.kwargs)
                    self.gen = gen
                    self.value = await gen.__anext__()
                except Exception as e:
                    self.exception = e
                    raise
                return self.value


class CachedAsyncGenByArguments(CachedAsyncGen):
    """Save the result of the 1st yield.
    Yield 2nd yield when all callers have yielded.
    We cache based off arguments."""

    def __init__(self, wrapped_func):
        super().__init__(wrapped_func)
        self.callers_by_args = {}

    def __call__(self, *args, **kwargs):
        # TODO: Handle cases where args are the same, but kwargs differ
        if args in self.callers_by_args:
            gen = self.callers_by_args[args]
        else:
            gen = CachedAsyncGen(self.wrapped_func)
            self.callers_by_args[args] = gen
        return gen(*args, **kwargs)


async def _make_asyncgen_fixture(
    _fixtureinfo: FuncFixtureInfo, fixture: FixtureDef, item: Item
):
    fixture_values, teardowns = await _fill_fixture_fixtures(
        _fixtureinfo, fixture, item
    )

    func: Union[CachedAsyncGen, CachedAsyncGenByArguments]

    if fixture.scope in ["module", "session"]:
        if not isinstance(fixture.func, CachedAsyncGenByArguments):
            fixture.func = CachedAsyncGenByArguments(fixture.func)
        func = fixture.func

    elif fixture.scope in ["function"]:
        try:
            func = item._asyncio_cooperative_cached_functions[fixture]
        except AttributeError:
            func = CachedAsyncGen(fixture.func)
            item._asyncio_cooperative_cached_functions = {fixture: func}
        except KeyError:
            func = CachedAsyncGen(fixture.func)

        item._asyncio_cooperative_cached_functions[fixture] = func

    gen = func(*fixture_values)
    value = await gen.__anext__()
    return value, [gen] + teardowns


async def _make_coroutine_fixture(
    _fixtureinfo: FuncFixtureInfo, fixture: FixtureDef, item: Item
):
    fixture_values, teardowns = await _fill_fixture_fixtures(
        _fixtureinfo, fixture, item
    )

    # Cache the module call
    if fixture.scope in ["module", "session"]:
        if not isinstance(fixture.func, CachedFunction):
            fixture.func = CachedFunction(fixture.func)
        value = await fixture.func(*fixture_values)
    elif fixture.scope in ["function"]:
        try:
            func = item._asyncio_cooperative_cached_functions[fixture]
        except AttributeError:
            func = CachedFunction(fixture.func)
            item._asyncio_cooperative_cached_functions = {fixture: func}
        except KeyError:
            func = CachedFunction(fixture.func)

        item._asyncio_cooperative_cached_functions[fixture] = func

        value = await func(*fixture_values)
    else:
        raise Exception("unknown scope type")

    return value, teardowns


async def _make_regular_generator_fixture(
    _fixtureinfo: FuncFixtureInfo, fixture: FixtureDef, item: Item
):
    fixture_values, teardowns = await _fill_fixture_fixtures(
        _fixtureinfo, fixture, item
    )

    if fixture.scope in ["module", "session"]:
        if not isinstance(fixture.func, CachedGen):
            fixture.func = CachedGen(fixture.func)
        func = fixture.func

    elif fixture.scope in ["function"]:
        try:
            func = item._asyncio_cooperative_cached_functions[fixture]
        except AttributeError:
            func = CachedGen(fixture.func)
            item._asyncio_cooperative_cached_functions = {fixture: func}
        except KeyError:
            func = CachedGen(fixture.func)

        item._asyncio_cooperative_cached_functions[fixture] = func

    gen = func(*fixture_values)
    return gen.__next__(), [gen] + teardowns


async def _make_regular_fixture(
    _fixtureinfo: FuncFixtureInfo, fixture: FixtureDef, item: Item
):
    # FIXME: we should use more of pytest's fixture system
    fixture_values, teardowns = await _fill_fixture_fixtures(
        _fixtureinfo, fixture, item
    )

    # Cache the module call
    if fixture.scope in ["module", "session"]:
        if not isinstance(fixture.func, CachedFunction):
            fixture.func = CachedFunction(fixture.func)
        value = await fixture.func(*fixture_values)
    elif fixture.scope in ["function"]:
        try:
            func = item._asyncio_cooperative_cached_functions[fixture]
        except AttributeError:
            func = CachedFunction(fixture.func)
            item._asyncio_cooperative_cached_functions = {fixture: func}
        except KeyError:
            func = CachedFunction(fixture.func)

        item._asyncio_cooperative_cached_functions[fixture] = func

        value = await func(*fixture_values)
    else:
        raise Exception("unknown scope type")

    return value, teardowns


async def fill_fixture_fixtures(
    _fixtureinfo: FuncFixtureInfo,
    fixture: Union[FixtureDef, FixtureRequest],
    item: Item,
):
    if isinstance(fixture, FixtureRequest):
        return fixture, []

    fixture.func = resolve_fixture_function(fixture, item._request)

    if inspect.isasyncgenfunction(fixture.func) or isinstance(
        fixture.func, CachedAsyncGen
    ):
        return await _make_asyncgen_fixture(_fixtureinfo, fixture, item)

    elif inspect.iscoroutinefunction(fixture.func) or isinstance(
        fixture.func, CachedFunction
    ):
        return await _make_coroutine_fixture(_fixtureinfo, fixture, item)

    elif inspect.isgeneratorfunction(fixture.func) or isinstance(
        fixture.func, CachedGen
    ):
        return await _make_regular_generator_fixture(_fixtureinfo, fixture, item)

    elif inspect.isfunction(fixture.func) or inspect.ismethod(fixture.func):
        return await _make_regular_fixture(_fixtureinfo, fixture, item)

    else:
        raise Exception(
            f"Something is strange about the fixture '{fixture.func.__name__}'.\n"
            f"Please create an issue with reproducible sample on github."
        )

import asyncio
import collections.abc
import inspect
import threading
import time
from sys import version_info as sys_version_info

import pytest
from _pytest.skipping import Skip
from _pytest.skipping import evaluate_skip_marks

from .assertion import activate_assert_rewrite
from .fixtures import fill_fixtures
from .integration.hypothesis import hypothesis_test_wrapper


def pytest_addoption(parser):
    parser.addoption(
        "--max-asyncio-tasks",
        action="store",
        default=None,
        help="asyncio: maximum number of tasks to run concurrently (int)",
    )
    parser.addini(
        "max_asyncio_tasks",
        "asyncio: maximum number of tasks to run concurrently (int)",
        default=100,
    )

    parser.addoption(
        "--asyncio-task-timeout",
        action="store",
        default=None,
        help="asyncio: number of seconds before a test will be cancelled (int)",
    )
    parser.addini(
        "asyncio_task_timeout",
        "asyncio: number of seconds before a test will be cancelled (int)",
        default=600,
    )


def pytest_configure(config):
    config.addinivalue_line(
        "markers",
        "asyncio_cooperative: run an async test cooperatively with other async tests.",
    )
    config.addinivalue_line(
        "markers", "flakey: if this test fails then run it one more time."
    )


@pytest.hookspec
def pytest_runtest_makereport(item, call):
    # Tests are run outside of the normal place, so we have to inject our timings

    if call.when == "call":
        if hasattr(item, "start") and hasattr(item, "stop"):
            call.start = item.start
            call.stop = item.stop
            call.duration = call.stop - call.start

    elif call.when == "setup":
        if hasattr(item, "start_setup") and hasattr(item, "stop_setup"):
            call.start = item.start_setup
            call.stop = item.stop_setup
            call.duration = call.stop - call.start

    elif call.when == "teardown":
        if hasattr(item, "start_teardown") and hasattr(item, "stop_teardown"):
            call.start = item.start_teardown
            call.stop = item.stop_teardown
            call.duration = call.stop - call.start


async def test_wrapper(item):
    # Do setup
    item.start_setup = time.time()
    fixture_values, teardowns = await fill_fixtures(item)
    item.stop_setup = time.time()

    # This is a class method test so prepend `self`
    if item.instance:
        fixture_values.insert(0, item.instance)

    async def do_teardowns():
        item.start_teardown = time.time()
        for teardown in teardowns:
            if isinstance(teardown, collections.abc.Iterator):
                try:
                    teardown.__next__()
                except StopIteration:
                    pass
            else:
                try:
                    await teardown.__anext__()
                except StopAsyncIteration:
                    pass
        item.stop_teardown = time.time()

    # Run test
    item.start = time.time()
    try:
        if inspect.iscoroutinefunction(item.function):
            await item.function(*fixture_values)
        else:
            item.function(*fixture_values)
    except:
        # Teardown here otherwise we might leave fixtures with locks acquired
        item.stop = time.time()
        await do_teardowns()
        raise

    item.stop = time.time()
    await do_teardowns()


def item_to_task(item):
    if getattr(item.function, "is_hypothesis_test", False):
        return hypothesis_test_wrapper(item)
    else:
        return test_wrapper(item)


def get_coro(task):
    if sys_version_info >= (3, 8):
        return task.get_coro()
    else:
        return task._coro


def cancel_task(task, now, item):
    if sys_version_info >= (3, 9):
        msg = "Test took too long ({:.2f} s)".format(now - item.enqueue_time)
        task.cancel(msg=msg)
    else:
        task.cancel()


def wrap_in_sync(item, result):
    def outer():
        def sync_wrapper():
            new_task = item_to_task(item)

            # We use a new thread because we can't block for an async function
            # in the same thread as the current running event loop, nor
            # we can nest event loops
            result = None

            def run_in_thread():
                nonlocal result
                try:
                    result = asyncio.run(new_task)
                except Exception as e:
                    result = e

            thread = threading.Thread(target=run_in_thread)
            thread.start()
            thread.join()

            if isinstance(result, Exception):
                raise result  # type: ignore

            return result

        item.runtest = sync_wrapper

        return result.result()

    return outer


async def run_tests(tasks, max_tasks: int, session, item_by_coro):
    flakes_to_retry = []

    sidelined_tasks = tasks[max_tasks:]
    tasks = tasks[:max_tasks]

    task_timeout = int(
        session.config.getoption("--asyncio-task-timeout")
        or session.config.getini("asyncio_task_timeout")
    )

    completed = []
    cancelled = []
    while tasks:
        # Schedule all the coroutines
        for i in range(len(tasks)):
            if asyncio.iscoroutine(tasks[i]):
                tasks[i] = asyncio.create_task(tasks[i])

        # Mark when the task was started
        earliest_enqueue_time = time.time()
        for task in tasks:
            if isinstance(task, asyncio.Task):
                item = item_by_coro[get_coro(task)]
            else:
                item = item_by_coro[task]
            if not hasattr(item, "enqueue_time"):
                item.enqueue_time = time.time()
            earliest_enqueue_time = min(item.enqueue_time, earliest_enqueue_time)

        time_to_wait = (time.time() - earliest_enqueue_time) - task_timeout
        done, pending = await asyncio.wait(
            tasks,
            return_when=asyncio.FIRST_COMPLETED,
            timeout=min(30, int(time_to_wait)),
        )

        # Cancel tasks that have taken too long
        tasks = []
        for task in pending:
            now = time.time()
            item = item_by_coro[get_coro(task)]
            if task not in cancelled and task_timeout < now - item.enqueue_time:
                cancel_task(task, now, item)
                cancelled.append(task)
            tasks.append(task)

        for result in done:
            item = item_by_coro[get_coro(result)]

            # Flakey tests will be run again if they failed
            # TODO: add retry count
            if item._flakey:
                try:
                    result.result()
                except:
                    item._flakey = None
                    new_task = item_to_task(item)
                    flakes_to_retry.append(new_task)
                    item_by_coro[new_task] = item
                    continue

            # We need to change .runtest to a synchronous function for pytest
            # however, if it is called again by retry libraries we need to rerun
            # the test instead of retuning the previous result
            item.runtest = wrap_in_sync(item, result)

            item.ihook.pytest_runtest_protocol(item=item, nextitem=None)

            # Hack: See rewrite comment below
            # pytest_runttest_protocl will disable the rewrite assertion
            # so we renable it here
            activate_assert_rewrite(item)

            completed.append(result)

        if sidelined_tasks:
            if len(tasks) < max_tasks:
                tasks.append(sidelined_tasks.pop(0))

    return flakes_to_retry


def _run_test_loop(tasks, session, item_by_coro):
    max_tasks = int(
        session.config.getoption("--max-asyncio-tasks")
        or session.config.getini("max_asyncio_tasks")
    )

    loop = asyncio.new_event_loop()
    try:
        return loop.run_until_complete(
            run_tests(tasks, int(max_tasks), session, item_by_coro)
        )
    finally:
        loop.close()


@pytest.hookimpl(hookwrapper=True, tryfirst=True)
def pytest_runtestloop(session):
    if session.config.pluginmanager.is_registered("asyncio"):
        raise Exception(
            "pytest-asyncio-cooperative is NOT compatible with pytest-asyncio\n"
            "Uninstall pytest-asyncio or pass this option to pytest: `-p no:asyncio`\n"
        )

    # pytest-cooperative needs to hijack the runtestloop from pytest.
    # To prevent the default pytest runtestloop from running tests we make it think we
    # were only collecting tests. Slightly a hack, but it is needed for other plugins
    # which use the pytest_runtestloop hook.
    previous_collectonly = session.config.option.collectonly
    session.config.option.collectonly = True
    yield
    session.config.option.collectonly = previous_collectonly

    session.wrapped_fixtures = {}

    # Collect our coroutines
    regular_items = []
    item_by_coro = {}
    tasks = []
    for item in session.items:
        markers = {m.name: m for m in item.own_markers}

        if "skip" in markers or "skipif" in markers:
            # Best to hand off to the core pytest logic to handle this so reporting works
            if isinstance(evaluate_skip_marks(item), Skip):
                regular_items.append(item)
                continue

        # Coerce into a task
        if "asyncio_cooperative" in markers:
            task = item_to_task(item)

            item._flakey = "flakey" in markers
            item_by_coro[task] = item
            tasks.append(task)
        else:
            regular_items.append(item)

    # Do assert rewrite
    # Hack: pytest's implementation sets up assert rewriting as a shared
    # resource. This causes a race condition between async tests. Therefore we
    # need to activate the assert rewriting here
    if tasks:
        item = item_by_coro[tasks[0]]
        activate_assert_rewrite(item)

    if previous_collectonly:
        return

    # Run the tests using cooperative multitasking
    flakes_to_retry = _run_test_loop(tasks, session, item_by_coro)

    # Run failed flakey tests
    if flakes_to_retry:
        _run_test_loop(flakes_to_retry, session, item_by_coro)

    # Run synchronous tests
    session.items = regular_items
    for i, item in enumerate(session.items):
        nextitem = session.items[i + 1] if i + 1 < len(session.items) else None
        item.config.hook.pytest_runtest_protocol(item=item, nextitem=nextitem)
        if session.shouldfail:
            raise session.Failed(session.shouldfail)
        if session.shouldstop:
            raise session.Interrupted(session.shouldstop)

    return True

import asyncio


class Lock:
    def __call__(self):
        try:
            return self.lock
        except AttributeError:
            self.lock = asyncio.Lock()
            return self.lock

import inspect
import sys

import pytest

from pytest_asyncio_cooperative.fixtures import CachedGen


def my_function():
    yield "Hello, World!"


@pytest.mark.skipif(sys.version_info < (3, 10), reason="Requires Python 3.10+")
def test_isgeneratorfunction_duck_typing():
    wrapped = CachedGen(my_function)
    assert inspect.isgeneratorfunction(wrapped)

def test_cached_function_can_handle_kwargs(testdir):
    testdir.makepyfile(
        """
        import pytest


        @pytest.mark.asyncio_cooperative
        async def test_a(pytestconfig):
            pass


        def test_b(pytestconfig):
            pass

    """
    )
    result = testdir.runpytest()
    result.assert_outcomes(passed=2)

from typing import List


pytest_plugins = ["pytester"]


def includes_lines(expected_lines: List[str], lines: List[str]) -> bool:
    for line in lines:
        for i, eline in enumerate(list(expected_lines)):
            if eline == line:
                expected_lines.pop(i)
                break

    assert expected_lines == []
    return expected_lines == []


def includes_lines_in_order(expected_lines: List[str], lines: List[str]) -> bool:
    try:
        for line in lines:
            if expected_lines[0] == line:
                expected_lines.pop(0)
    except IndexError:
        pass

    assert expected_lines == []
    return expected_lines == []

import pytest


@pytest.mark.parametrize(
    "dur1, dur2, expectedfails, expectedpasses",
    [
        (1.1, 2, 2, 0),
        (2, 2, 2, 0),
    ],
